// Written by scripts/icon-art.py from design/icons. Do not edit by hand:
// change the art there and run it again.

/// The 56 icons drawn for Ablox: the dock, the closet, the game
/// categories, the play screen and Studio's tools. Each is a 128 px WebP in
/// base64, 377 KB for all of them, kept here so the Playground needs no
/// resource bundle (see docs/icons.md). An icon that cannot be read shows its
/// SF Symbol (`fallbackSymbol`) instead.
public enum DrawnIcon: String, CaseIterable, Sendable, Identifiable {
    case badgeDifficulty = "badge-difficulty"
