enum IconArt {

    private static let lock = NSLock()
    private static var decoded: [DrawnIcon: UIImage] = [:]

    /// The icon's picture, decoded the first time it is asked for.
    static func image(_ icon: DrawnIcon) -> UIImage? {
        lock.lock()
        defer { lock.unlock() }
        if let image = decoded[icon] { return image }
        guard let data = Data(base64Encoded: text(for: icon), options: .ignoreUnknownCharacters),
              let image = UIImage(data: data, scale: 2) else { return nil }
        decoded[icon] = image
        return image
    }

