/// A drawn icon at a size, or its symbol while it cannot be drawn.
public struct DrawnIconImage: View {
    private let icon: DrawnIcon
    private let size: CGFloat

    public init(_ icon: DrawnIcon, size: CGFloat = 32) {
        self.icon = icon
        self.size = size
    }

    public var body: some View {
        picture
            .aspectRatio(contentMode: .fit)
            .frame(width: size, height: size)
            .accessibilityHidden(true)
    }

    private var picture: Image {
        if let image = IconArt.image(icon) { return Image(uiImage: image).resizable().interpolation(.high) }
        return Image(systemName: icon.fallbackSymbol).resizable()
    }
}
